import{_ as a,o as r,c as t,a5 as n}from"./chunks/framework.QWVCgkrI.js";const o="/study/images/algorithms/bounding-volume-hierarchies.svg",m=JSON.parse('{"title":"BVHとAABB — 箱でまとめて衝突候補を絞る","description":"","frontmatter":{"title":"BVHとAABB — 箱でまとめて衝突候補を絞る","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"algorithms","summary":"物体を囲む箱を階層にして候補を絞り、箱の重なりと物体の移動が問い合わせに及ぼす影響を調べる。","aliases":["BVH","Bounding Volume Hierarchy","境界ボリューム階層","AABB","軸平行境界ボックス","動的AABB木","broad phase","ブロードフェーズ","レイキャスト","refit","リフィット"],"verification":"pbrtのBVH実装、Box2DのDynamic Tree API、KoptaらのBVH更新論文に照合（2026-11-06）"}},"headers":[],"relativePath":"algorithms/bounding-volume-hierarchies.md","filePath":"algorithms/bounding-volume-hierarchies.md"}'),s={name:"algorithms/bounding-volume-hierarchies.md"};function i(d,e,l,c,h,p){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="bvhとaabb-—-箱でまとめて衝突候補を絞る" tabindex="-1">BVHとAABB — 箱でまとめて衝突候補を絞る <a class="header-anchor" href="#bvhとaabb-—-箱でまとめて衝突候補を絞る" aria-label="Permalink to &quot;BVHとAABB — 箱でまとめて衝突候補を絞る&quot;">​</a></h1><p>画面上の範囲にいる敵を探すには、すべての敵の形状を検索範囲と照合する方法があります。遠くの敵をまとめて除外できれば、形状を調べる回数を減らせます。**BVH（Bounding Volume Hierarchy）**は、物体を囲む領域を階層にまとめ、各領域を調べて内側の物体を検索候補に含めるか決めるデータ構造です。<a href="https://www.pbr-book.org/4ed/Primitives_and_Intersection_Acceleration/Bounding_Volume_Hierarchies" target="_blank" rel="noreferrer">pbrtのBVH解説と実装</a></p><h2 id="物体を分け、囲む箱を階層にする" tabindex="-1">物体を分け、囲む箱を階層にする <a class="header-anchor" href="#物体を分け、囲む箱を階層にする" aria-label="Permalink to &quot;物体を分け、囲む箱を階層にする&quot;">​</a></h2><p>**AABB（Axis-Aligned Bounding Box）**は、各辺が座標軸と平行な境界ボックスです。2Dなら <code>minX, minY, maxX, maxY</code> の4値で表せます。円なら中心の各成分から半径を引いた値が最小、足した値が最大です。箱は物体全体を含むので、箱に届かない問い合わせは内側の物体にも届きません。内側に空きがあるため、箱に届いた段階では物体との交差は未確定です。<a href="https://www.pbr-book.org/4ed/Geometry_and_Transformations/Bounding_Boxes" target="_blank" rel="noreferrer">pbrtの境界ボックス実装</a></p><p>ここで扱うBVHでは物体の集合を二つのグループに分け、各グループを再帰的に分けます。各物体は一つの葉だけに入ります。内部ノードでは子の箱を囲む箱を持ちます。例えば親の <code>minX</code> は子の <code>minX</code> の最小、親の <code>maxX</code> は子の <code>maxX</code> の最大です。グループ間で物体を共有しなくても、箱が囲む空間は重なり得ます。<a href="/study/algorithms/uniform-grid-and-spatial-hash.html">均等グリッド</a>や<a href="/study/algorithms/quadtrees-and-octrees.html">四分木・八分木</a>は、先に空間を区画へ分けます。<a href="https://www.pbr-book.org/4ed/Primitives_and_Intersection_Acceleration/Bounding_Volume_Hierarchies" target="_blank" rel="noreferrer">pbrtの物体分割と空間分割</a></p><figure class="study-figure"><img src="'+o+`" alt="円AとBを枝1、円CとDを枝2に割り当てた例。二つの枝の箱は一部が重なる。問い合わせの矩形が枝1の箱にだけ重なるのでAとBを個別に調べ、Aだけがヒットする。枝2のCとDは個別判定を省く。" width="760" height="374" loading="lazy"><figcaption>子の箱は一部が重なります。この問い合わせでは、枝2をまとめて除外できます。<a href="/study/images/algorithms/bounding-volume-hierarchies.svg" target="_blank" rel="noopener noreferrer">BVHの図を拡大</a></figcaption></figure><h2 id="箱で枝を絞り、葉で実際の形状を調べる" tabindex="-1">箱で枝を絞り、葉で実際の形状を調べる <a class="header-anchor" href="#箱で枝を絞り、葉で実際の形状を調べる" aria-label="Permalink to &quot;箱で枝を絞り、葉で実際の形状を調べる&quot;">​</a></h2><p>図の矩形問い合わせは根の箱に重なります。次に枝1と枝2の箱を調べ、重ならない枝2を除外します。枝1の葉にあるAとBは候補です。円と矩形の正確な交差を調べると、Aだけが残ります。矩形の各軸の範囲へ円の中心座標を収めると、矩形内で円の中心に最も近い点を得られます。その点までの距離の二乗が半径の二乗以下なら、接する場合も含めてヒットです。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>query(node, area):</span></span>
<span class="line"><span>    if node is empty or disjoint(node.bounds, area):</span></span>
<span class="line"><span>        return</span></span>
<span class="line"><span>    if node is a leaf:</span></span>
<span class="line"><span>        for each object in node:</span></span>
<span class="line"><span>            if intersects(object.shape, area):</span></span>
<span class="line"><span>                report(object)</span></span>
<span class="line"><span>        return</span></span>
<span class="line"><span>    for each child of node:</span></span>
<span class="line"><span>        query(child, area)</span></span></code></pre></div><p>接触を含める場合、箱の片方の最大値がもう片方の最小値と等しいときも調べます。箱の重なりを見たノード数を <code>v</code>、正確に調べた物体数を <code>c</code> とすると、各判定のコストが一定なこの例では <code>O(v + c)</code> です。問い合わせが広い場合や子の箱の重なりが多い場合は、両方の枝へ進む箇所が増えます。木の高さを抑えても訪問先が一経路に絞られるとは限らず、1回の問い合わせが全物体を調べる場合もあります。<a href="https://www.pbr-book.org/4ed/Primitives_and_Intersection_Acceleration/Bounding_Volume_Hierarchies" target="_blank" rel="noreferrer">pbrtのBVH走査と箱の重なり</a></p><h2 id="物体が動いたら箱や木を更新する" tabindex="-1">物体が動いたら箱や木を更新する <a class="header-anchor" href="#物体が動いたら箱や木を更新する" aria-label="Permalink to &quot;物体が動いたら箱や木を更新する&quot;">​</a></h2><table tabindex="0"><thead><tr><th>更新方法</th><th>変えるもの</th><th>観察すること</th></tr></thead><tbody><tr><td>初回構築・再構築（build / rebuild）</td><td>現在の配置から物体をグループに分け直し、木と箱を作る</td><td>構築コストと、その後に何回問い合わせを行うか</td></tr><tr><td>箱の再計算（refit）</td><td>葉の箱を更新し、親の箱を子から順に計算し直す。所属グループは維持する</td><td>物体が離れると箱が広がり、除外しにくくなる場合がある</td></tr><tr><td>動的木での局所更新</td><td>動いた物体を別の枝へ付け直すなど、一部の構造を変える</td><td>移動・追加・削除にかかる時間と、問い合わせで訪れたノード数</td></tr></tbody></table><p>pbrtはレイとプリミティブの交差を絞るためにBVHを構築します。Box2Dの動的AABB木では、物体の代理データを葉に持たせて範囲問い合わせやレイキャストを行います。例えば <code>b2DynamicTree_MoveProxy</code> は移動した代理データを木から外し、新しいAABBで挿入し直します。物理の<strong>ブロードフェーズ</strong>ではこのような木で衝突候補を集め、その後に実際の形状を照合します。レイキャストでも、箱との交差を通過した葉で形状との交差を調べます。<a href="https://www.pbr-book.org/4ed/Primitives_and_Intersection_Acceleration/Bounding_Volume_Hierarchies" target="_blank" rel="noreferrer">pbrtの構築と走査</a> · <a href="https://box2d.org/documentation/group__tree.html" target="_blank" rel="noreferrer">Box2DのDynamic Tree API</a> · <a href="https://hwrt.cs.utah.edu/papers/hwrt_rotations.pdf" target="_blank" rel="noreferrer">Koptaらのリフィットと局所更新の論文</a></p><p><a href="/study/practice/algorithms/spatial-query-observation.html">範囲問い合わせの実験</a>では、円の中心で物体をおおむね半分ずつに分け、葉に最大4個の円を置いた2DのBVHを使います。範囲を動かしながら、BVH、全件検索、均等グリッドで候補数とヒット結果を比べられます。3D描画での使い方は<a href="/study/graphics/lighting/raytracing.html">ハードウェアレイトレーシング</a>で扱います。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/math/physics-integration-and-collision.html">物理の時間積分と衝突判定</a>で、候補に残った形状の交差を調べる。</li></ul>`,16)])])}const b=a(s,[["render",i]]);export{m as __pageData,b as default};
